Shell(sleep 1; B=http://localhost:4000/api PTOK=$(curl -s -X POST $B/auth/login -H 'Content-Type: application/json' -d '{"email":"rahim@mail.com","password":"password123"}' | node -e "let s='';process.stdin.on('data',d=>s+=d).on('end',()=>console.log(JSON.parse(s).data.token))") DTOK=$(curl -s -X POST $B/auth/login -H 'Content-Type: application/json' -d '{"email":"sarah@clinic.com","password":"password123"}' | node -e "let s='';process.stdin.on('data',d=>s+=d).on('end',()=>console.log(JSON.parse(s).data.token))") ATOK=$(curl -s -X POST $B/auth/login -H 'Content-Type: application/json' -d '{"email":"admin@smartmed.com","password":"admin12345"}' | node -e "let s='';process.stdin.on('data',d=>s+=d).on('end',()=>console.log(JSON.parse(s).data.token))") echo "tokens: P=${#PTOK} D=${#DTOK} A=${#ATOK}" echo "--- sample collection: create (patient) ---" curl -s -X POST $B/sample-collections -H "Authorization: Bearer $PTOK" -H 'Content-Type: application/json' -d '{"testName":"CBC","address":"House 12, Road 5, Gulshan, Dhaka","scheduledAt":"2026-08-18T09:00:00Z"}' -o /tmp/sm_sc.json -w "http %{http_code}
" SCID=$(node -e "console.log(require('/tmp/sm_sc.json').data.collection.id)") echo "sc id: $SCID status: $(node -e "console.log(require('/tmp/sm_sc.json').data.collection.status)")" echo "--- assign lab assistant (admin) ---" curl -s -X PATCH $B/sample-collections/$SCID/assign -H "Authorization: Bearer $ATOK" -H 'Content-Type: application/json' -d '{"labAssistantId":"00000000-0000-4000-8000-000000000001"}' -o /tmp/sm_sca.json -w "http %{http_code}
" node -e "const j=require('/tmp/sm_sca.json');console.log('status:',j.data.collection.status,'assistant:',j.data.collection.labAssistant.name)" echo "--- patient cannot assign (expect 403) ---" curl -s -X PATCH $B/sample-collections/$SCID/assign -H "Authorization: Bearer $PTOK" -H 'Content-Type: application/json' -d '{"labAssistantId":"00000000-0000-4000-8000-000000000001"}' -w "
http %{http_code}
" echo "--- ambulance: create booking (patient) ---" curl -s -X POST $B/ambulance-bookings -H "Authorization: Bearer $PTOK" -H 'Content-Type: application/json' -d '{"pickupLocation":"Dhanmondi","dropLocation":"Dhaka Medical College Hospital","type":"BASIC"}' -o /tmp/sm_ab.json -w "http %{http_code}
" ABID=$(node -e "console.log(require('/tmp/sm_ab.json').data.booking.id)") echo "booking id: $ABID status: $(node -e "console.log(require('/tmp/sm_ab.json').data.booking.status)")" echo "--- assign ambulance (admin) ---" curl -s -X PATCH $B/ambulance-bookings/$ABID/assign -H "Authorization: Bearer $ATOK" -H 'Content-Type: application/json' -d '{"ambulanceId":"00000000-0000-4000-8000-000000000002"}' -o /tmp/sm_aba.json -w "http %{http_code}
" node -e "const j=require('/tmp/sm_aba.json');console.log('booking status:',j.data.booking.status,'ambulance:',j.data.booking.ambulance.vehicleNo)" echo "--- ambulance now BUSY, assign again to a new booking (expect 400) ---" curl -s -X POST $B/ambulance-bookings -H "Authorization: Bearer $PTOK" -H 'Content-Type: application/json' -d '{"pickupLocation":"Uttara","dropLocation":"Square Hospital","type":"BASIC"}' > /dev/null ABID2=$(curl -s "$B/ambulance-bookings/mine" -H "Authorization: Bearer $PTOK" | node -e "let s='';process.stdin.on('data',d=>s+=d).on('end',()=>{const l=JSON.parse(s).data.bookings;console.log(l.find(b=>b.status==='REQUESTED').id)})") curl -s -X PATCH $B/ambulance-bookings/$ABID2/assign -H "Authorization: Bearer $ATOK" -H 'Content-Type: application/json' -d '{"ambulanceId":"00000000-0000-4000-8000-000000000002"}' -w "
http %{http_code}
" echo "--- health record: doctor writes for confirmed appointment ---" curl -s -X PATCH $B/appointments/487f1fcf-d8eb-47c6-938b-e43bf0709b0f/status -H "Authorization: Bearer $DTOK" -H 'Content-Type: application/json' -d '{"status":"COMPLETED"}' > /dev/null curl -s -X POST $B/health-records -H "Authorization: Bearer $DTOK" -H 'Content-Type: application/json' -d '{"appointmentId":"487f1fcf-d8eb-47c6-938b-e43bf0709b0f","prescriptionText":"Paracetamol 500mg twice daily for 5 days","notes":"Patient advised rest and hydration"}' -o /tmp/sm_hr.json -w "http %{http_code}
" node -e "const j=require('/tmp/sm_hr.json');console.log('record id:',j.data.record.id,'doctor:',j.data.record.doctor.user.name)" echo "--- duplicate record (expect 409) ---" curl -s -X POST $B/health-records -H "Authorization: Bearer $DTOK" -H 'Content-Type: application/json' -d '{"appointmentId":"487f1fcf-d8eb-47c6-938b-e43bf0709b0f","prescriptionText":"X"}' -w "
http %{http_code}
" echo "--- patient lists records ---" curl -s "$B/health-records" -H "Authorization: Bearer $PTOK" -o /tmp/sm_hrl.json -w "http %{http_code}
" node -e "const j=require('/tmp/sm_hrl.json');console.log('records:',j.data.pagination.total)" echo "--- review: patient reviews doctor (completed appt exists) ---" DPID=$(curl -s -X POST $B/auth/login -H 'Content-Type: application/json' -d '{"email":"sarah@clinic.com","password":"password123"}' | node -e "let s='';process.stdin.on('data',d=>s+=d).on('end',()=>console.log(JSON.parse(s).data.user.doctorProfile.id))") curl -s -X POST $B/reviews -H "Authorization: Bearer $PTOK" -H 'Content-Type: application/json' -d "{"doctorId":"$DPID","rating":5,"comment":"Very professional"}" -o /tmp/sm_rv.json -w "http %{http_code}
" node -e "const j=require('/tmp/sm_rv.json');console.log('review rating:',j.data.review.rating)" echo "--- duplicate review (expect 409) ---" curl -s -X POST $B/reviews -H "Authorization: Bearer $PTOK" -H 'Content-Type: application/json' -d "{"doctorId":"$DPID","rating":4}" -w "
http %{http_code}
" echo "--- public list reviews for doctor ---" curl -s "$B/reviews/doctor/$DPID" -o /tmp/sm_rvl.json -w "http %{http_code}
" node -e "const j=require('/tmp/sm_rvl.json');console.log('avg:',j.data.summary.averageRating,'count:',j.data.summary.totalReviews)")

